// Tools offered to the LLM (function declarations) and the code that really executes them.
//
// Security rules enforced HERE (in code, not by the prompt):
//  1. No tool has a subscriberNo parameter. The subscriber number and JWT always come from the
//     logged-in session, so a number written in the chat can never reach another account.
//  2. pay_bill never pays directly: the agent asks the human for explicit confirmation first
//     (subscriber, period, amount). Only a "yes" typed by the user triggers the Pay Bill API.
//  3. The transaction ID is generated by the agent (idempotency key for the API).

const crypto = require('crypto');

const period = {
  month: { type: 'integer', minimum: 1, maximum: 12, description: 'Billing month, 1-12' },
  year: { type: 'integer', minimum: 2000, maximum: 2100, description: 'Billing year, e.g. 2026' },
};

const TOOL_DECLARATIONS = [
  {
    name: 'search_billing_documentation',
    description:
      'Search the mobile provider billing guide (policy document) via MCP. Use for general rules: pricing, ' +
      'included allowances, extra internet/phone charges, how bills are calculated, due dates, partial payments, ' +
      'payment confirmation, late payments, service restriction, disputes. Returns passages with section numbers. ' +
      'Contains NO subscriber-specific data.',
    parametersJsonSchema: {
      type: 'object',
      properties: {
        query: { type: 'string', description: 'Search keywords in English, e.g. "extra internet charges"' },
        maxResults: { type: 'integer', minimum: 1, maximum: 8, description: 'Number of passages (default 3)' },
      },
      required: ['query'],
    },
  },
  {
    name: 'query_bill',
    description:
      "Get the logged-in subscriber's stored bill for a month: total, paid amount, remaining balance, status, due date. " +
      'Live data from the Billing API (through the API Gateway).',
    parametersJsonSchema: { type: 'object', properties: { ...period }, required: ['month', 'year'] },
  },
  {
    name: 'query_bill_detailed',
    description:
      "Get the logged-in subscriber's detailed bill for a month: phone minutes, internet MB/GB, charge breakdown " +
      'and paged usage records. Use it to explain WHY a bill has a certain amount. Requires the user to be logged in.',
    parametersJsonSchema: {
      type: 'object',
      properties: { ...period, page: { type: 'integer', minimum: 1, description: 'Page of usage records (default 1)' } },
      required: ['month', 'year'],
    },
  },
  {
    name: 'pay_bill',
    description:
      "Request a (simulated) payment for the logged-in subscriber's bill. Partial or full amount. " +
      'The application will ask the user to confirm before anything is paid, so do NOT ask for confirmation yourself; ' +
      'call this tool once you know the month, year and amount. If the user wants to pay the whole bill, first call ' +
      'query_bill and use the remaining balance as amount.',
    parametersJsonSchema: {
      type: 'object',
      properties: { ...period, amount: { type: 'number', description: 'Amount in USD, > 0, max 2 decimals' } },
      required: ['month', 'year', 'amount'],
    },
  },
];

const MCP_TOOLS = new Set(['search_billing_documentation']);

function newTransactionId() {
  return `AGT-${Date.now()}-${crypto.randomBytes(3).toString('hex')}`;
}

function checkPeriod({ month, year }) {
  if (!Number.isInteger(month) || month < 1 || month > 12) return 'month must be an integer 1-12';
  if (!Number.isInteger(year) || year < 2000 || year > 2100) return 'year must be a 4-digit year';
  return null;
}

function apiError(err) {
  return { error: { status: err.status ?? 0, code: err.code || 'ERROR', message: err.message } };
}

/**
 * @param {object} deps
 * @param {object} deps.billing   billing REST client (through the gateway)
 * @param {object} deps.mcp       connected MCP client
 * @param {object} deps.session   { subscriberNo, token, username }
 * @param {function} deps.confirmPayment async ({subscriberNo, year, month, amount}) => boolean
 */
function createToolExecutor({ billing, mcp, session, confirmPayment, txIdFactory = newTransactionId }) {
  async function run(name, rawArgs = {}) {
    const args = { ...rawArgs };
    const ignored = {};
    // Whatever the model sends, account identity is never taken from tool arguments.
    for (const k of ['subscriberNo', 'subscriber_no', 'subscriber', 'token']) {
      if (k in args) { ignored[k] = args[k]; delete args[k]; }
    }
    const channel = MCP_TOOLS.has(name) ? 'MCP' : 'REST via API Gateway';
    const base = { channel, ...(Object.keys(ignored).length ? { ignoredArgs: ignored } : {}) };
    const { subscriberNo, token } = session;

    switch (name) {
      case 'search_billing_documentation': {
        if (typeof args.query !== 'string' || args.query.trim().length < 2) {
          return { ...base, request: 'search_billing_documentation', result: { error: { code: 'INVALID_ARGS', message: 'query is required' } } };
        }
        const maxResults = args.maxResults ?? 3;
        try {
          const result = await mcp.searchDocs(args.query, maxResults);
          return { ...base, request: `search_billing_documentation(${JSON.stringify(args.query)})`, result };
        } catch (err) {
          return { ...base, request: 'search_billing_documentation', result: { error: { code: 'MCP_ERROR', message: err.message } } };
        }
      }

      case 'query_bill': {
        const bad = checkPeriod(args);
        const request = `GET /api/v1/bills?subscriberNo=${subscriberNo}&year=${args.year}&month=${args.month}`;
        if (bad) return { ...base, request, result: { error: { code: 'INVALID_ARGS', message: bad } } };
        try {
          return { ...base, request, result: await billing.queryBill({ subscriberNo, year: args.year, month: args.month }) };
        } catch (err) {
          return { ...base, request, result: apiError(err) };
        }
      }

      case 'query_bill_detailed': {
        const bad = checkPeriod(args);
        const page = Number.isInteger(args.page) && args.page > 0 ? args.page : 1;
        const request = `GET /api/v1/bills/detailed?subscriberNo=${subscriberNo}&year=${args.year}&month=${args.month}&page=${page}&pageSize=10  [JWT]`;
        if (bad) return { ...base, request, result: { error: { code: 'INVALID_ARGS', message: bad } } };
        try {
          return { ...base, request, result: await billing.queryBillDetailed({ token, subscriberNo, year: args.year, month: args.month, page, pageSize: 10 }) };
        } catch (err) {
          return { ...base, request, result: apiError(err) };
        }
      }

      case 'pay_bill': {
        const bad = checkPeriod(args) || (!(typeof args.amount === 'number' && args.amount > 0) ? 'amount must be a positive number' : null);
        if (bad) return { ...base, request: 'POST /api/v1/payments', result: { error: { code: 'INVALID_ARGS', message: bad } } };
        const amount = Math.round(args.amount * 100) / 100;
        const details = { subscriberNo, year: args.year, month: args.month, amount };

        const confirmed = await confirmPayment(details);
        if (!confirmed) {
          return {
            ...base,
            confirmation: 'DECLINED',
            request: 'POST /api/v1/payments (not sent)',
            result: { paymentStatus: 'NOT_SUBMITTED', reason: 'The user did not confirm the payment. Nothing was paid.' },
          };
        }
        const transactionId = txIdFactory();
        const request = `POST /api/v1/payments {subscriberNo:${subscriberNo}, year:${args.year}, month:${args.month}, amount:${amount}, transactionId:${transactionId}}  [JWT]`;
        try {
          const result = await billing.payBill({ token, ...details, transactionId });
          return { ...base, confirmation: 'CONFIRMED', request, result };
        } catch (err) {
          return { ...base, confirmation: 'CONFIRMED', request, result: apiError(err) };
        }
      }

      default:
        return { ...base, request: name, result: { error: { code: 'UNKNOWN_TOOL', message: `No tool named ${name}` } } };
    }
  }

  return { run };
}

module.exports = { TOOL_DECLARATIONS, createToolExecutor, newTransactionId };
